;; curriculum: Multivariable (undergrad) — saddle points; prerequisites: gradient, contour
;; math target: a saddle is a minimum along one path and a maximum along another; the pass is both at once.

app riya-level-saddle "1.1.0"
"riya level 26 · The Mountain Pass — the trail z = 2 + x²/12 dips to its minimum at x = 0, but the cross-trail z = 4 − y²/6 peaks there: one point, a minimum and a maximum at once. A crosswall drift shoves you back toward the trail whenever you climb too high. Descend to the pass and climb out. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup, rendered through math-canvas."

;; @exposure internal

orbital RiyaSaddleOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaSaddleBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaSaddlePlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaSaddleFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  type RiyaSaddleFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaSaddlePickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaSaddleCurveSample = {
    x : number!
    y : number!
  }
  type RiyaSaddleCurve = {
    label : string
    color : string
    samples : [RiyaSaddleCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaSaddleGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaSaddleFieldVector = {
    x : number!
    y : number!
    vx : number!
    vy : number!
    color : string
    label : string
  }
  type RiyaSaddleDriftRegion = {
    id : string!
    x0 : number!
    x1 : number!
    y0 : number!
    y1 : number!
    ax : number!
    ay : number!
  }

  entity RiyaSaddleState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaSaddleBody = { x: -9, y: 9.6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaSaddlePickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaSaddleFx] = []
    celebrated : boolean = false
    platforms : [RiyaSaddlePlatform] = []
    curves : [RiyaSaddleCurve] = []
    guides : [RiyaSaddleGuide] = []
    fieldVectors : [RiyaSaddleFieldVector] = []
    zoneId : string = "saddle"
  }
  entity SaddleTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }


  trait SaddleBody = Body.traits.PlatformerBody -> RiyaSaddleState {
    events {
      STEER: SADDLE_STEER
      JUMP: SADDLE_LEAP
      PLACE: SADDLE_PLACE
      RESTART: SADDLE_RESTART
      BODY_JUMPED: SADDLE_JUMPED
      BODY_LANDED: SADDLE_LANDED
      BODY_HAZARD: SADDLE_HAZARD
      BODY_GOAL: SADDLE_GOAL
      BODY_FELL: SADDLE_FELL
      BODY_SKATE_START: SADDLE_SKATE_ON
      BODY_SKATE_END: SADDLE_SKATE_OFF
      SET_PLATFORMS: SADDLE_SET_PLATFORMS
      SET_SKATE_CURVE: SADDLE_SET_SKATE_CURVE
      SET_DRIFT_REGIONS: SADDLE_SET_DRIFT_REGIONS
    }
    config {
      running: true
      spawn: { x: -9, y: 9.6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: false
      skateSnap: 0.9
    }
  }

  trait SaddleGate = Gate.traits.ObjectiveFlow -> RiyaSaddleState {
    events {
      PROGRESS: SADDLE_PROGRESS
      GAME_END: SADDLE_GAME_END
      RESTART: SADDLE_RESTART
    }
    config { running: true }
  }

  trait SaddleFx = Particles.traits.FxParticles -> RiyaSaddleState {
    events {
      BURST: SADDLE_BURST
    }
    config { running: true }
  }

  trait SaddlePickup = Pickup.traits.Pickup -> RiyaSaddleState {
    events {
      PICKED: SADDLE_PICKED
      COLLECT: SADDLE_COLLECT
      PICKUP_SET_COMPLETED: SADDLE_PICKUP_SET_COMPLETED
      SET_FEATURES: SADDLE_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }


  trait SaddleLevelData -> @rebindable RiyaSaddleState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "saddle"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          driftRegions: (array/map @config.driftRegions (fn d @d))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          fieldVectors: (array/map @config.fieldVectors (fn v @v))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSaddlePlatform]!
        stars : [RiyaSaddlePickup]!
        skateCurve : [RiyaSaddleCurveSample]
        driftRegions : [RiyaSaddleDriftRegion]
        curveOverlay : [RiyaSaddleCurve]
        guides : [RiyaSaddleGuide]
        fieldVectors : [RiyaSaddleFieldVector]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Mountain Pass"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "z = 2 + x²/12"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the pass is the trail's minimum and the cross-trail's maximum at once — a saddle point"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 8.45
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 8.45
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaSaddlePlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 10.45, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 8.32, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 6.61, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 5.33, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 4.48, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 4.05, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 4.05, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 4.48, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 5.33, type: "ground" }
        { id: "b9", x: 4.8, y: -2, width: 1.6, height: 6.61, type: "ground" }
