  trait RiyaSaddlePlay -> @rebindable RiyaSaddleState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit SADDLE_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "SADDLE_LEFT", KeyA: "SADDLE_LEFT", ArrowRight: "SADDLE_RIGHT", KeyD: "SADDLE_RIGHT", ArrowUp: "SADDLE_JUMP", KeyW: "SADDLE_JUMP", Space: "SADDLE_JUMP" }
            keyUpMap: { ArrowLeft: "SADDLE_STOP", KeyA: "SADDLE_STOP", ArrowRight: "SADDLE_STOP", KeyD: "SADDLE_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: (array/concat [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.9), vx: (* @entity.body.vx 0.5), vy: (* @entity.body.vy 0.5), color: @config.riyaColor, label: "v" } ] @entity.fieldVectors)
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "SADDLE_LEFT", right: "SADDLE_RIGHT", up: "SADDLE_JUMP" }, directionReleaseEvents: { left: "SADDLE_STOP", right: "SADDLE_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "saddle")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.fieldVectors @payload.fieldVectors)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit SADDLE_SET_PLATFORMS { platforms: @payload.platforms })
        (emit SADDLE_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit SADDLE_SET_DRIFT_REGIONS { regions: @payload.driftRegions })
        (emit SADDLE_SET_FEATURES { features: @payload.stars })

      SADDLE_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SADDLE_STEER { dir: -1 })

      SADDLE_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SADDLE_STEER { dir: 1 })

      SADDLE_STOP -> idle when (== @entity.active true)
        (emit SADDLE_STEER { dir: 0 })

      SADDLE_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SADDLE_LEAP {})

      SADDLE_FELL -> idle when (== @entity.active true)
        (emit SADDLE_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit SADDLE_BURST { particles: (array/map [ "fx-saddle-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      SADDLE_SKATE_ON -> idle when (== @entity.active true)
        (emit SADDLE_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "saddle point: min one way, max the other", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-saddle-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat "x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      SADDLE_PICKED -> idle when (== @entity.active true)
        (emit SADDLE_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: @payload.glyph, ttl: 2 })) })
      SADDLE_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit SADDLE_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      SADDLE_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit SADDLE_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "pass = min along trail, max across trail", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit SADDLE_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      SADDLE_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "saddle" })


      SADDLE_TUTORIAL_DONE -> idle
        (emit SADDLE_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "the pass: min along the trail, max across it", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
