            vectors: (array/concat [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.9), vx: (* @entity.body.vx 0.5), vy: (* @entity.body.vy 0.5), color: @config.riyaColor, label: "v" } ] @entity.fieldVectors)
          } ]
        })
    }

    emits {
      SADDLE_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      SADDLE_RIGHT -> external {
