      height : number = 480
        @label "Canvas Height"
        @tier "presentation"
    }
  }

  trait SaddleChallenge -> @rebindable RiyaSaddleState [game-core, instance] {
    initial: idle

    state idle {
      SADDLE_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "tilt")
          (emit SADDLE_BURST { particles: (array/concat
            { id: "narrative-boost-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "cross-trail z = 4 − y²/6", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            { id: "narrative-boost-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.6), y: 0, message: "the ridge across", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          ) })
          null)
    }

    emits {
      SADDLE_BURST -> external {
        particles : [RiyaSaddleFx]
      }
        @description "Particle batch spawned on the tilt pickup's cross-trail narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      SADDLE_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "saddle"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaSaddleClear -> @rebindable RiyaSaddleState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "SADDLE_NEXT", variant: "primary" } ]
        })

      SADDLE_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      SADDLE_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-saddle"
        @label "Next Path"
        @tier "presentation"
      clearTitle : string = "Saddle clear"
        @label "Clear Title"
        @tier "presentation"
      clearSubtitle : string = "Minimum and maximum at once."
        @label "Clear Subtitle"
        @tier "presentation"
    }
  }

  page "/riya-saddle" as RiyaSaddlePage -> SaddleLevelData, SaddleBody, SaddleGate, SaddleFx, SaddlePickup, SaddleTutorial, RiyaSaddleGenre, RiyaSaddlePlay, SaddleChallenge, RiyaSaddleClear
}
